<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { CheckCircle2, ClipboardCopy, DatabaseBackup, Download, Globe2, Image, KeyRound, Link2, MoonStar, RotateCcw, ShieldCheck, Trash2, Unlink, Upload, UserRound } from 'lucide-vue-next'
import BrandMark from '../components/BrandMark.vue'
import { api } from '../api'
import { auth } from '../auth'
import { preferences, t, tr, type Locale, type Theme } from '../preferences'
import type { APIToken, BackupInspection, OIDCIdentity, RuntimeSettings, TOTPEnrollment } from '../types'
import { appVersion } from '../version'

const router = useRouter()
const info = ref<RuntimeSettings | null>(null)
const enrollment = ref<TOTPEnrollment | null>(null)
const code = ref('')
const error = ref('')
const notice = ref('')
const recoveryCodes = ref<string[]>([])
const busy = ref(false)
const oidcIdentities = ref<OIDCIdentity[]>([])
const oidcBusy = ref(false)
const backupBusy = ref(false)
const backupCandidate = ref<File | null>(null)
const backupInspection = ref<BackupInspection | null>(null)
const apiTokens = ref<APIToken[]>([])
const apiTokenName = ref('RustDesk deployment')
const apiTokenTTL = ref(30)
const newAPIToken = ref('')
const apiTokenBusy = ref(false)
const logoFile = ref<File | null>(null)
const logoBusy = ref(false)
const globalAvatarFile = ref<File | null>(null)
const globalAvatarBusy = ref(false)
const securityBusy = ref(false)
const security = ref({require_login:true,require_device_deployment:false,registration_enabled:false,registration_auto_approve:false,access_token_ttl:'168h',session_ttl:'168h',mfa_mode:'optional' as RuntimeSettings['mfa_mode'],password_minimum_length:12,password_require_upper:true,password_require_lower:true,password_require_number:true,password_require_special:true})

async function load() { try { info.value = await api.settings(); Object.assign(security.value,{require_login:info.value.require_login,require_device_deployment:info.value.require_device_deployment,registration_enabled:info.value.registration_enabled,registration_auto_approve:info.value.registration_auto_approve,access_token_ttl:info.value.access_token_ttl,session_ttl:info.value.session_ttl,mfa_mode:info.value.mfa_mode,password_minimum_length:info.value.password_minimum_length,password_require_upper:info.value.password_require_upper,password_require_lower:info.value.password_require_lower,password_require_number:info.value.password_require_number,password_require_special:info.value.password_require_special}) } catch (reason) { error.value = reason instanceof Error ? reason.message : tr('Настройки недоступны','Settings unavailable') } }
async function saveSecurity(){securityBusy.value=true;error.value='';notice.value='';try{info.value=await api.updateSettings(security.value);notice.value=tr('Настройки безопасности сохранены и переданы HBBS.','Security settings were saved and propagated to HBBS.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось сохранить настройки','Could not save settings')}finally{securityBusy.value=false}}
async function copyServerKey() {
  if (!info.value?.server_public_key) return
  try { await navigator.clipboard.writeText(info.value.server_public_key); notice.value=tr('Ключ сервера скопирован.','Server key copied.') }
  catch { error.value=tr('Не удалось скопировать ключ. Выделите его вручную.','Could not copy the key. Select it manually.') }
}
async function backupSQLite(){backupBusy.value=true;error.value='';notice.value='';try{const result=await api.sqliteBackup();const url=URL.createObjectURL(result.blob);const link=document.createElement('a');link.href=url;link.download=result.filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);notice.value=tr('Резервная копия SQLite создана и загружена.','SQLite backup created and downloaded.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось создать резервную копию','Could not create backup')}finally{backupBusy.value=false}}
function selectBackup(event:Event){backupCandidate.value=(event.target as HTMLInputElement).files?.[0]||null;backupInspection.value=null;error.value=''}
async function inspectBackup(){if(!backupCandidate.value)return;backupBusy.value=true;error.value='';notice.value='';try{backupInspection.value=await api.inspectSQLiteBackup(backupCandidate.value);notice.value=tr('Копия прошла проверку целостности и совместимости. Рабочая база не изменялась.','The backup passed integrity and compatibility checks. The active database was not changed.')}catch(reason){backupInspection.value=null;error.value=reason instanceof Error?reason.message:tr('Копия повреждена или несовместима','The backup is corrupt or incompatible')}finally{backupBusy.value=false}}
async function loadOIDC() { try { oidcIdentities.value = await api.oidcIdentities() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'OIDC identities unavailable' } }
async function linkOIDC() {
  const popup = window.open('about:blank', 'rustdesk-oidc-link', 'popup,width=720,height=760')
  oidcBusy.value=true;error.value='';notice.value=''
  try {
    const flow=await api.beginOIDCLink()
    if (popup) popup.location.href=flow.url; else window.open(flow.url,'_blank','noopener,noreferrer')
    for(let attempt=0;attempt<180;attempt+=1){
      await new Promise((resolve)=>window.setTimeout(resolve,1000))
      const result=await api.pollOIDCLink(flow.code)
      if(!('pending' in result)){oidcIdentities.value=await api.oidcIdentities();notice.value=tr(`Учётная запись ${result.provider} привязана.`,`${result.provider} account linked.`);popup?.close();return}
    }
    error.value=tr('Время ожидания привязки OIDC истекло.','OIDC linking timed out.')
  } catch(reason){popup?.close();error.value=reason instanceof Error?reason.message:tr('Не удалось привязать OIDC','Could not link OIDC')} finally{oidcBusy.value=false}
}
async function unlinkOIDC(value:OIDCIdentity){if(!window.confirm(tr(`Удалить привязку ${value.provider} (${value.email||value.subject})?`,`Unlink ${value.provider} (${value.email||value.subject})?`)))return;oidcBusy.value=true;error.value='';try{await api.unlinkOIDC(value);await loadOIDC();notice.value=tr('OIDC-привязка удалена.','OIDC identity unlinked.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось удалить привязку','Could not unlink identity')}finally{oidcBusy.value=false}}
async function loadAPITokens(){try{apiTokens.value=await api.apiTokens()}catch(reason){error.value=reason instanceof Error?reason.message:'API tokens unavailable'}}
async function createAPIToken(){apiTokenBusy.value=true;error.value='';newAPIToken.value='';try{const result=await api.createAPIToken(apiTokenName.value,apiTokenTTL.value);newAPIToken.value=result.token;await loadAPITokens();notice.value=tr('Токен создан. Скопируйте его сейчас — повторно он не показывается.','Token created. Copy it now; it will not be shown again.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось создать токен','Could not create token')}finally{apiTokenBusy.value=false}}
async function revokeAPIToken(value:APIToken){if(!window.confirm(tr(`Отозвать токен «${value.name}»?`,`Revoke token “${value.name}”?`)))return;apiTokenBusy.value=true;try{await api.revokeAPIToken(value.id);await loadAPITokens();notice.value=tr('API-токен отозван.','API token revoked.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось отозвать токен','Could not revoke token')}finally{apiTokenBusy.value=false}}
async function copyAPIToken(){if(!newAPIToken.value)return;try{await navigator.clipboard.writeText(newAPIToken.value);notice.value=tr('API-токен скопирован.','API token copied.')}catch{error.value=tr('Не удалось скопировать токен.','Could not copy token.')}}
function selectLogo(event:Event){logoFile.value=(event.target as HTMLInputElement).files?.[0]||null;error.value=''}
async function uploadLogo(){if(!logoFile.value)return;logoBusy.value=true;error.value='';notice.value='';try{await api.uploadLogo(logoFile.value);logoFile.value=null;if(info.value)info.value.custom_logo=true;window.dispatchEvent(new Event('rds-branding-changed'));notice.value=tr('Логотип обновлён.','Logo updated.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось загрузить логотип','Could not upload logo')}finally{logoBusy.value=false}}
async function resetLogo(){logoBusy.value=true;error.value='';notice.value='';try{await api.resetLogo();if(info.value)info.value.custom_logo=false;window.dispatchEvent(new Event('rds-branding-changed'));notice.value=tr('Восстановлен стандартный логотип.','Default logo restored.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось восстановить логотип','Could not restore logo')}finally{logoBusy.value=false}}
function selectGlobalAvatar(event:Event){globalAvatarFile.value=(event.target as HTMLInputElement).files?.[0]||null;error.value=''}
async function uploadGlobalAvatar(){if(!globalAvatarFile.value)return;globalAvatarBusy.value=true;error.value='';try{await api.uploadGlobalAvatar(globalAvatarFile.value);globalAvatarFile.value=null;if(info.value)info.value.custom_global_avatar=true;notice.value=tr('Глобальный аватар обновлён.','Global avatar updated.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось загрузить аватар','Could not upload avatar')}finally{globalAvatarBusy.value=false}}
async function resetGlobalAvatar(){globalAvatarBusy.value=true;error.value='';try{await api.resetGlobalAvatar();if(info.value)info.value.custom_global_avatar=false;notice.value=tr('Глобальный аватар удалён.','Global avatar removed.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось удалить аватар','Could not remove avatar')}finally{globalAvatarBusy.value=false}}
async function enroll() { busy.value=true;error.value='';notice.value='';try{enrollment.value=await api.enrollTOTP();recoveryCodes.value=enrollment.value.recovery_codes;code.value=''}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось начать настройку 2FA','Could not start 2FA setup')}finally{busy.value=false} }
async function confirm() { busy.value=true;error.value='';try{await api.confirmTOTP(code.value);await auth.logout();await router.replace('/admin/login')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось подтвердить код','Could not confirm code')}finally{busy.value=false} }
async function disable() { busy.value=true;error.value='';try{await api.disableTOTP(code.value);await auth.logout();await router.replace('/admin/login')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось отключить 2FA','Could not disable 2FA')}finally{busy.value=false} }
async function regenerate() { busy.value=true;error.value='';try{const result=await api.regenerateRecoveryCodes(code.value);recoveryCodes.value=result.recovery_codes;code.value='';notice.value=tr('Старые recovery-коды отозваны. Сохраните новый набор.','Old recovery codes were revoked. Save the new set.')}catch(reason){error.value=reason instanceof Error?reason.message:tr('Не удалось обновить recovery-коды','Could not regenerate recovery codes')}finally{busy.value=false} }
onMounted(()=>{void Promise.all([load(),loadOIDC(),loadAPITokens()])})
</script>

<template>
  <section class="section-heading"><div><p class="eyebrow">Configuration</p><h2>{{t('runtimeSettings')}}</h2><p>{{t('settingsHelp')}}</p></div></section>
  <p v-if="error" class="alert-error">{{error}}</p><p v-if="notice" class="alert-success">{{notice}}</p>
  <section class="settings-grid">
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">Security</p><h3>{{tr('Политика входа','Sign-in policy')}}</h3></div><ShieldCheck :size="20"/></div><div class="security-toggle-list"><label class="check-label"><input v-model="security.require_login" type="checkbox" :disabled="!auth.can('settings.write')"/><span>{{t('requireLogin')}}</span></label><label class="check-label"><input v-model="security.require_device_deployment" type="checkbox" :disabled="!auth.can('settings.write')"/><span>{{tr('Только предварительно добавленные устройства','Require device enrollment')}}</span></label><label class="check-label"><input v-model="security.registration_enabled" type="checkbox" :disabled="!auth.can('settings.write')"/><span>{{tr('Разрешить самостоятельную регистрацию','Allow self-registration')}}</span></label><label class="check-label registration-child"><input v-model="security.registration_auto_approve" type="checkbox" :disabled="!security.registration_enabled||!auth.can('settings.write')"/><span>{{tr('Автоматически авторизовывать новых пользователей','Automatically approve new users')}}</span></label><small v-if="security.registration_auto_approve" class="setting-hint">{{tr('Новые зарегистрированные пользователи сразу попадут в группу «Авторизованные пользователи» и смогут подключаться согласно ACL.','New registrations immediately join the “Approved users” group and can connect according to ACL.')}}</small></div><label><span>{{tr('Режим 2FA','2FA mode')}}</span><select v-model="security.mfa_mode" :disabled="!auth.can('settings.write')"><option value="optional">{{tr('Необязательно','Optional')}}</option><option value="required_for_admins">{{tr('Обязательно администраторам','Required for admins')}}</option><option value="required_for_all_users">{{tr('Обязательно всем','Required for everyone')}}</option></select></label><div class="form-grid"><label><span>{{t('tokenTtl')}}</span><input v-model.trim="security.access_token_ttl" placeholder="168h" :disabled="!auth.can('settings.write')"/></label><label><span>{{t('sessionTtl')}}</span><input v-model.trim="security.session_ttl" placeholder="168h" :disabled="!auth.can('settings.write')"/></label></div><fieldset class="password-policy"><legend>{{tr('Политика паролей','Password policy')}}</legend><label><span>{{tr('Минимальная длина','Minimum length')}}</span><input v-model.number="security.password_minimum_length" type="number" min="8" max="128" :disabled="!auth.can('settings.write')"/></label><div><label class="check-label"><input v-model="security.password_require_upper" type="checkbox"/><span>{{tr('Заглавная буква','Uppercase letter')}}</span></label><label class="check-label"><input v-model="security.password_require_lower" type="checkbox"/><span>{{tr('Строчная буква','Lowercase letter')}}</span></label><label class="check-label"><input v-model="security.password_require_number" type="checkbox"/><span>{{tr('Цифра','Number')}}</span></label><label class="check-label"><input v-model="security.password_require_special" type="checkbox"/><span>{{tr('Специальный символ','Special character')}}</span></label></div></fieldset><button class="primary-button compact" :disabled="securityBusy||!auth.can('settings.write')" @click="saveSecurity"><CheckCircle2 :size="16"/>{{securityBusy?tr('Сохранение…','Saving…'):tr('Сохранить политику','Save policy')}}</button><dl class="settings-list"><div><dt>{{tr('Блокировка учётной записи','Account lockout')}}</dt><dd>{{info?.login_burst}} / {{info?.login_window}} · {{info?.login_lockout}}</dd></div><div><dt>Generic OIDC</dt><dd>{{info?.oidc_enabled?`ON · ${info.oidc_provider}`:'OFF'}}</dd></div><div><dt>LDAP / Active Directory</dt><dd>{{info?.ldap_enabled?`ON · ${info?.ldap_auto_provision?tr('автоматическое создание','auto-provision'):tr('только связанные','linked only')}`:'OFF'}}</dd></div><div><dt>{{t('relayServer')}}</dt><dd>{{info?.relay_server||'—'}}</dd></div><div><dt>{{t('database')}}</dt><dd>{{info?.database_driver||'—'}}</dd></div></dl></article>
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">Console</p><h3>{{tr('Внешний вид','Appearance')}}</h3></div><MoonStar :size="20"/></div><label class="setting-control"><span><MoonStar :size="17"/>{{t('theme')}}</span><select :value="preferences.state.theme" @change="preferences.setTheme(($event.target as HTMLSelectElement).value as Theme)"><option value="system">{{t('system')}}</option><option value="dark">{{t('dark')}}</option><option value="light">{{t('light')}}</option></select></label><label class="setting-control"><span><Globe2 :size="17"/>{{t('language')}}</span><select :value="preferences.state.locale" @change="preferences.setLocale(($event.target as HTMLSelectElement).value as Locale)"><option value="ru">Русский</option><option value="en">English</option></select></label><div class="console-logo-setting"><div class="console-logo-preview"><BrandMark/><div><strong>{{tr('Логотип консоли','Console logo')}}</strong><small>{{info?.custom_logo?tr('Пользовательский','Custom'):tr('Стандартный','Default')}}</small></div></div><p>{{tr('PNG или SVG, не более 2 МБ. Изображение автоматически вписывается в существующий размер.','PNG or SVG, up to 2 MiB. The image automatically fits the existing logo area.')}}</p><label class="logo-file"><Image :size="17"/><input type="file" accept=".png,.svg,image/png,image/svg+xml" :disabled="logoBusy||!auth.can('settings.write')" @change="selectLogo"/><span>{{logoFile?.name||tr('Выбрать файл','Choose file')}}</span></label><div class="logo-actions"><button class="secondary-button" :disabled="logoBusy||!logoFile||!auth.can('settings.write')" @click="uploadLogo"><Upload :size="16"/>{{logoBusy?tr('Сохранение…','Saving…'):tr('Загрузить','Upload')}}</button><button class="secondary-button" :disabled="logoBusy||!info?.custom_logo||!auth.can('settings.write')" @click="resetLogo"><RotateCcw :size="16"/>{{tr('Стандартный логотип','Default logo')}}</button></div></div></article>
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">Managed deployment</p><h3>{{tr('API-токены RustDesk','RustDesk API tokens')}}</h3></div><KeyRound :size="20"/></div><p>{{tr('Используйте токен в команде','Use the token with')}} <code>rustdesk --deploy --token …</code>. {{tr('На сервере хранится только SHA-256.','Only its SHA-256 hash is stored on the server.')}}</p><dl class="settings-list"><div><dt>{{tr('Обязательное добавление устройств','Require device enrollment')}}</dt><dd>{{info?.require_device_deployment?'ON':'OFF'}}</dd></div></dl><label><span>{{tr('Название','Name')}}</span><input v-model.trim="apiTokenName" maxlength="128" placeholder="RustDesk deployment"/></label><label><span>{{tr('Срок действия, дней','Lifetime, days')}}</span><input v-model.number="apiTokenTTL" type="number" min="1" max="365"/></label><button class="secondary-button" :disabled="apiTokenBusy||!apiTokenName||apiTokenTTL<1||apiTokenTTL>365" @click="createAPIToken"><KeyRound :size="16"/>{{tr('Создать токен','Create token')}}</button><div v-if="newAPIToken" class="recovery-codes"><strong>{{tr('Скопируйте токен сейчас','Copy the token now')}}</strong><code>{{newAPIToken}}</code><button class="secondary-button" @click="copyAPIToken"><ClipboardCopy :size="16"/>{{tr('Скопировать','Copy')}}</button></div><div v-if="apiTokens.length" class="identity-list"><div v-for="item in apiTokens" :key="item.id"><div><strong>{{item.name}}</strong><small>{{item.prefix}}… · {{tr('до','until')}} {{new Date(item.expires_at).toLocaleDateString()}}{{item.revoked_at?` · ${tr('отозван','revoked')}`:''}}</small></div><button v-if="!item.revoked_at" class="icon-action" :title="tr('Отозвать токен','Revoke token')" :disabled="apiTokenBusy" @click="revokeAPIToken(item)"><Trash2 :size="17"/></button></div></div></article>
    <article class="panel settings-card server-key-card"><div class="panel-heading"><div><p class="overline">End-to-end encryption</p><h3>{{tr('Ключ сервера RustDesk','RustDesk server key')}}</h3></div><KeyRound :size="20"/></div><p>{{tr('Укажите это значение в поле','Enter this value in the')}} <strong>Key</strong> {{tr('официального RustDesk Client. Пустой или старый ключ вызывает предупреждение «Небезопасное подключение».','field of the official RustDesk Client. A missing or stale key causes an “Insecure connection” warning.')}}</p><code class="server-public-key">{{info?.server_public_key||tr('Публичный ключ недоступен','Public key unavailable')}}</code><button class="secondary-button" :disabled="!info?.server_public_key" @click="copyServerKey"><ClipboardCopy :size="16"/>{{tr('Скопировать ключ','Copy key')}}</button></article>
    <article v-if="auth.can('backup.read')" class="panel settings-card"><div class="panel-heading"><div><p class="overline">Disaster recovery</p><h3>{{tr('Резервная копия базы','Database backup')}}</h3></div><DatabaseBackup :size="20"/></div><p v-if="info?.database_driver==='sqlite'">{{tr('Создаёт согласованный snapshot SQLite через online backup. Загруженную копию можно безопасно проверить без изменения рабочей базы.','Creates a consistent online SQLite snapshot. An uploaded copy can be safely inspected without changing the active database.')}}</p><p v-else>{{tr('Для PostgreSQL используйте штатный pg_dump и внешнюю систему резервного копирования.','For PostgreSQL, use pg_dump and an external backup system.')}}</p><button class="secondary-button" :disabled="backupBusy||info?.database_driver!=='sqlite'" @click="backupSQLite"><Download :size="16"/>{{backupBusy?tr('Обработка…','Processing…'):tr('Скачать SQLite backup','Download SQLite backup')}}</button><label class="logo-file"><DatabaseBackup :size="17"/><input type="file" accept=".db,.sqlite,.sqlite3,application/vnd.sqlite3" :disabled="backupBusy||info?.database_driver!=='sqlite'" @change="selectBackup"/><span>{{backupCandidate?.name||tr('Выбрать backup для проверки','Choose backup to inspect')}}</span></label><button class="secondary-button" :disabled="backupBusy||!backupCandidate" @click="inspectBackup"><ShieldCheck :size="16"/>{{tr('Проверить целостность','Inspect integrity')}}</button><dl v-if="backupInspection" class="settings-list"><div><dt>SQLite quick_check</dt><dd>{{backupInspection.quick_check}}</dd></div><div><dt>{{tr('Таблицы','Tables')}}</dt><dd>{{backupInspection.schema_tables}}</dd></div><div><dt>{{tr('Пользователи','Users')}}</dt><dd>{{backupInspection.users}}</dd></div><div><dt>{{tr('Устройства','Devices')}}</dt><dd>{{backupInspection.devices}}</dd></div><div><dt>{{tr('Сессии','Sessions')}}</dt><dd>{{backupInspection.sessions}}</dd></div></dl></article>
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">Authenticator</p><h3>{{tr('Двухфакторная защита','Two-factor authentication')}}</h3></div><KeyRound :size="20"/></div><p>{{auth.state.user?.totp_enabled?tr('2FA включена для вашей учётной записи.','2FA is enabled for your account.'):tr('Добавьте секрет в совместимое TOTP-приложение и подтвердите шестизначным кодом.','Add the secret to a compatible TOTP application and confirm it with a six-digit code.')}}</p>
      <template v-if="!auth.state.user?.totp_enabled"><button v-if="!enrollment" class="secondary-button" :disabled="busy" @click="enroll">{{tr('Настроить 2FA','Set up 2FA')}}</button><template v-else><label class="setting-control"><span>{{tr('Секрет','Secret')}}</span><code>{{enrollment.secret}}</code></label><small>{{tr('Сохраните секрет в приложении-аутентификаторе.','Save the secret in your authenticator application.')}}</small><a class="text-button" :href="enrollment.otpauth_uri">{{tr('Открыть в аутентификаторе','Open in authenticator')}}</a><label><span>{{tr('Код подтверждения','Verification code')}}</span><input v-model="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="000000"/></label><button class="primary-button compact" :disabled="busy||code.length!==6" @click="confirm">{{tr('Подтвердить и включить','Confirm and enable')}}</button></template></template>
      <template v-else><label><span>{{tr('Текущий код подтверждения','Current verification code')}}</span><input v-model="code" inputmode="numeric" maxlength="11" autocomplete="one-time-code" placeholder="000000"/></label><div class="modal-actions"><button class="secondary-button" :disabled="busy||code.length<6" @click="regenerate">{{tr('Новые recovery-коды','New recovery codes')}}</button><button class="secondary-button" :disabled="busy||code.length!==6" @click="disable">{{tr('Отключить 2FA','Disable 2FA')}}</button></div></template>
      <div v-if="recoveryCodes.length" class="recovery-codes"><strong>{{tr('Recovery-коды показываются только сейчас','Recovery codes are shown only now')}}</strong><small>{{tr('Каждый код одноразовый. Храните их отдельно от пароля.','Each code can be used once. Store them separately from your password.')}}</small><code v-for="item in recoveryCodes" :key="item">{{item}}</code></div>
    </article>
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">Federated identity</p><h3>{{tr('Учётные записи OIDC','OIDC identities')}}</h3></div><Link2 :size="20"/></div><p v-if="!info?.oidc_enabled">{{tr('OIDC не настроен администратором сервера.','OIDC has not been configured by the server administrator.')}}</p><template v-else><p>{{tr('Привязка создаётся только после подтверждённого входа у провайдера. Пароль локальной учётной записи не передаётся.','The identity is linked only after a verified provider login. Your local account password is never shared.')}}</p><div v-if="oidcIdentities.length" class="identity-list"><div v-for="item in oidcIdentities" :key="`${item.provider}:${item.subject}`"><div><strong>{{item.provider}}</strong><small>{{item.email||item.subject}}</small></div><button class="icon-action" :title="tr('Удалить привязку','Remove link')" :disabled="oidcBusy" @click="unlinkOIDC(item)"><Unlink :size="17"/></button></div></div><button class="secondary-button" :disabled="oidcBusy" @click="linkOIDC"><Link2 :size="16"/>{{oidcBusy?tr('Ожидание провайдера…','Waiting for provider…'):tr('Привязать OIDC','Link OIDC')}}</button></template></article>
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">Connection identity</p><h3>{{tr('Глобальный аватар','Global avatar')}}</h3></div><UserRound :size="20"/></div><div class="avatar-setting"><img v-if="info?.custom_global_avatar" :src="`${info.global_avatar_url}?v=${Date.now()}`" alt=""/><div v-else class="avatar-placeholder">RD</div><div><strong>{{info?.custom_global_avatar?tr('Используется как резервный','Used as fallback'):tr('Не задан','Not configured')}}</strong><p>{{tr('Показывается в окне входящего подключения, если у пользователя нет персонального аватара. PNG или JPEG до 2 МБ.','Shown in the incoming connection window when the user has no personal avatar. PNG or JPEG up to 2 MiB.')}}</p></div></div><label class="logo-file"><Image :size="17"/><input type="file" accept=".png,.jpg,.jpeg,image/png,image/jpeg" :disabled="globalAvatarBusy||!auth.can('settings.write')" @change="selectGlobalAvatar"/><span>{{globalAvatarFile?.name||tr('Выбрать аватар','Choose avatar')}}</span></label><div class="logo-actions"><button class="secondary-button" :disabled="globalAvatarBusy||!globalAvatarFile||!auth.can('settings.write')" @click="uploadGlobalAvatar"><Upload :size="16"/>{{tr('Загрузить','Upload')}}</button><button class="secondary-button" :disabled="globalAvatarBusy||!info?.custom_global_avatar||!auth.can('settings.write')" @click="resetGlobalAvatar"><Trash2 :size="16"/>{{tr('Удалить','Remove')}}</button></div></article>
    <article class="panel settings-card"><div class="panel-heading"><div><p class="overline">About</p><h3>Remote Control Server · v{{appVersion}}</h3></div><BrandMark/></div><p><strong>Compatible with the RustDesk client protocol</strong></p><p>{{tr('Remote Control Server — независимый проект, не связанный с RustDesk. RustDesk является товарным знаком соответствующего правообладателя. Упоминание используется исключительно для обозначения протокольной совместимости.','Remote Control Server is an independent project and is not affiliated with RustDesk. RustDesk is a trademark of its respective owner; the name is used solely to describe protocol compatibility.')}}</p><small>created by blackxdog</small><a class="secondary-button support-link" href="https://boosty.to/blackxdog" target="_blank" rel="noopener noreferrer">{{tr('Поддержать проект на Boosty','Support the project on Boosty')}}</a></article>
  </section>
</template>
